import itertools
from collections import defaultdict

# Load and filter dictionary
with open("/workdir/data/dict.txt") as f:
    raw_words = f.read().strip().split('\n')

valid_words = set()
for w in raw_words:
    w_lower = w.lower()
    if len(w_lower) >= 4 and w_lower.isalpha():
        valid_words.add(w_lower)

print(f"Valid words: {len(valid_words)}")

# For each word, compute its "pattern" - the canonical form
def get_pattern(word):
    mapping = {}
    result = []
    counter = 0
    for ch in word:
        if ch not in mapping:
            mapping[ch] = chr(ord('a') + counter)
            counter += 1
        result.append(mapping[ch])
    return ''.join(result)

# Group words by pattern
pattern_groups = defaultdict(list)
for w in valid_words:
    p = get_pattern(w)
    pattern_groups[p].append(w)

print(f"Number of patterns: {len(pattern_groups)}")

# Find patterns with multiple words (potential for mapping)
multi_patterns = {p: words for p, words in pattern_groups.items() if len(words) >= 2}
print(f"Patterns with 2+ words: {len(multi_patterns)}")

# For each pair of words with the same pattern, extract the partial mapping
def extract_mapping(w1, w2):
    """Extract letter mapping from w1 to w2. Returns None if not compatible."""
    if len(w1) != len(w2):
        return None
    fwd = {}
    bwd = {}
    for c1, c2 in zip(w1, w2):
        if c1 in fwd:
            if fwd[c1] != c2:
                return None
        else:
            fwd[c1] = c2
        if c2 in bwd:
            if bwd[c2] != c1:
                return None
        else:
            bwd[c2] = c1
        if c1 == c2:
            return None  # derangement constraint
    return fwd

# Build mapping candidates from word pairs with same pattern
mapping_votes = defaultdict(lambda: {"count": 0, "words": set(), "chars": set()})

for pattern, words in multi_patterns.items():
    word_list = list(words)
    for i in range(len(word_list)):
        for j in range(len(word_list)):
            if i == j:
                continue
            w1, w2 = word_list[i], word_list[j]
            mp = extract_mapping(w1, w2)
            if mp:
                key = tuple(sorted(mp.items()))
                mapping_votes[key]["count"] += 1
                mapping_votes[key]["words"].add(w1)
                mapping_votes[key]["chars"].update(w1)

# Sort by word count
sorted_mappings = sorted(mapping_votes.items(), key=lambda x: -len(x[1]["words"]))

print("\nTop 10 mappings by word count:")
for key, info in sorted_mappings[:10]:
    print(f"  Mapping: {dict(key)}, Words: {len(info['words'])}, Chars: {len(info['chars'])}")
    print(f"  Sample words: {list(info['words'])[:10]}")

